@media print {
    html, body {
        margin: 0;
        padding: 0;
        background: none !important;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
        width: 210mm;
        height: 297mm;
        overflow: hidden;
        transform: scale(1.1);
        transform-origin: top left;
    }

    @page {
        size: A4;
        margin: 0; /* no padding or margin on print */
    }

    /* Main Letter Container */
    .letter-page {
        width: 100%;
        max-width: 210mm;
        min-height: 297mm;
        box-sizing: border-box;
        margin: 0 auto;
        padding: 0 !important;
        border: none !important;
        background: none !important;
        page-break-before: avoid;
        page-break-after: avoid;
        page-break-inside: avoid;
        break-before: avoid-page;
        break-after: avoid-page;
        break-inside: avoid-page;
    }

    /* Prevent splitting of main sections */
    .header-section,
    .letter-body,
    .letter-title,
    .letter-content,
    .signatures-section,
    .letter-footer {
        display: block !important;
        page-break-inside: avoid !important;
        break-inside: avoid-page !important;
        width: 100%;
    }

    /* Tables */
    table, tr, td, th, tbody, thead, tfoot {
        border-collapse: collapse !important;
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }

    /* Font tuning */
    body, td, th, span {
        color: #000 !important;
        line-height: 1.3 !important;
        vertical-align: top !important;
    }

    * {
        overflow: visible !important;
    }
    
    /* Watermark styling */
    .watermark {
        position: fixed;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        opacity: 0.2; /* 20% visibility */
        z-index: 0;
        font-size: 120px;
        color: #2d3436;
        font-weight: 700;
        text-transform: uppercase;
        white-space: nowrap;
        pointer-events: none;
        user-select: none;
    }

    /* Ensure all main content stays above watermark */
    .content, .letter-body, .letter-footer {
        position: relative;
        z-index: 1;
    }
}
